/* @category: shared */
/******************
 *  New Viewport  *
 ******************/

body.has-fullscreen {
  overflow: hidden;
  background: #ffffff;
  padding: 0;
  display: block;
}

.cX-Leaflet {
  position: absolute;
  visibility: visible;
  width: 100%;
  height: 100%;
  z-index: -1;
}

.cX-Viewer-Drag,
.cX-Viewer-Drag-Layout {
  position: absolute;
  background-color: rgba(204,204,204,0.7);
}

.cX-DOM {
  padding: 0;
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  width: var(--base-w);
  height: var(--base-h);
}

.cX-DOM:fullscreen {
  width: 100vw;
  height: 100vh;
  background-color: white;
  overflow-y: auto;
}

.cX-DOM:fullscreen::backdrop {
  background-color: black;
  opacity: 1 !important;
}

.cX-DOM.fullscreen-mode {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  margin: 0 !important;
  z-index: 1;
  background: transparent !important;
}

.cX-Wrapper {
  padding: 0;
  transition: width var(--cx-transition-speed) ease-out, height var(--cx-transition-speed) ease-out;
  position: relative;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  width: var(--base-w);
  height: var(--base-h);
}

.cX-Wrapper.resizing {
  transition: none !important;
}

.cX-Wrapper.resizing .cX-Container,
.cX-Wrapper.resizing .cX-Container-Cell {
  transition: none !important;
}


.cX-Container,
.CanvasXpress {
  width: 100%;
  height: 100%;
  transition: width var(--cx-transition-speed) ease, height var(--cx-transition-speed) ease;
}

.cX-Wrapper.fullscreen-mode {
  position: fixed !important;
  top: 0 !important;
  left: 0 !important;
  margin: 0 !important;
  z-index: 9999;
  border-radius: 0;
  background: #ffffff !important;
  height: 100vh !important;
  width: 100vw !important;
}

.cX-UI {
  display: flex;
  flex-direction: row;
  align-items: stretch;
  width: 100%;
  flex-grow: 1;
  position: relative;
}

.cX-Container {
  width: var(--base-w);
  height: var(--base-h);
  background-color: transparent;
  position: relative;
  flex-shrink: 0;
  transition: width var(--cx-transition-speed) ease, height var(--cx-transition-speed) ease;
}

.cX-Wrapper.fullscreen-mode .cX-Container {
  width: 100% !important;
  height: 100% !important;
}

.cX-Container-Cell {
  position: absolute;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  color: white;
  border: none;
  transition: all var(--cx-transition-speed) ease, opacity var(--cx-transition-speed) ease;
  opacity: 0;
  pointer-events: none;
  background: transparent;
}

.cX-Container-Cell.active {
  opacity: 1;
  pointer-events: auto;
}

.cX-Canvas-Container {
  margin: auto;
  display: flex;
  align-items: center;
}

/* Version Info Box */

.cX-Version-Info-Trigger {
  position: absolute;
  left: 0;
  top: 0;
  width: 25px;
  height: 25px;
  background: transparent;
  z-index: 10000;
  pointer-events: auto;
}

.cX-Version-Info-Container {
  position: absolute;
  left: 32px;
  top: 32px;
  border: var(--cx-border);
  border-radius: 10px;
  padding: 8px;
  background: #ffffff;
  opacity: 0;
  z-index: 1001;
  transition: all var(--cx-transition-speed) ease;
  overflow: hidden;
  white-space: nowrap;
  font: var(--cx-x-large-font);
  pointer-events: none;
}

.cX-Version-Info-Trigger:hover+.cX-Version-Info-Container {
  opacity: 1;
  pointer-events: auto;
}

/* HTML Widget Container */

.cX-Container-HTMLWidget {
  z-index: 100000;
  background: transparent;
  width: 100%;
  height: 100%;
  box-sizing: border-box;
  overflow: auto;
}

